<template>
  <MarketplaceLayout><main class="market-container market-page community-page"><div class="discussion">
    <header class="community-topline"><div><h1>Cộng đồng BonsaiMarket</h1><p>Cùng trao đổi về bonsai, sen đá và cách chăm cây.</p></div><RouterLink class="button button-primary" to="/community/create">Viết bài</RouterLink></header>
    <form class="community-filters" @submit.prevent="search"><label for="community-search">Tìm trong cộng đồng</label><input id="community-search" v-model="keyword" type="search" maxlength="160" placeholder="Tìm bài viết hoặc kinh nghiệm chăm cây"/><label for="community-topic">Chủ đề</label><select id="community-topic" v-model="topic"><option value="">Tất cả chủ đề</option><option v-for="(label,key) in topics" :key="key" :value="key">{{ label }}</option></select><button class="button button-outline">Tìm bài viết</button></form>
    <ResourceState v-if="loading || error" resource="bài viết" :loading="loading" :error="Boolean(error)" @retry="load"/>
    <template v-else><p role="status">{{ data.totalElements }} bài viết</p><ul v-if="data.content.length" class="community-list"><li v-for="post in data.content" :key="post.id"><span class="community-topic">{{ topics[post.topic] }}</span><h2><RouterLink :to="'/community/posts/'+post.id">{{ post.title }}</RouterLink></h2><p>{{ preview(post.body) }}</p><div class="discussion-meta">{{ post.authorName }} · <time :datetime="post.createdAt">{{ date(post.createdAt) }}</time></div></li></ul><p v-else class="discussion-empty">Chưa có bài viết phù hợp. Thử từ khóa khác hoặc chia sẻ câu chuyện về góc vườn của bạn.</p><CatalogPagination :page="data.page" :total-pages="data.totalPages" label="Phân trang bài viết"/></template>
  </div></main></MarketplaceLayout>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import CatalogPagination from '../../../components/marketplace/CatalogPagination.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics,date,preview} from '../../../services/discussions.js';import '../../../css/discussions.css';
const route=useRoute(),router=useRouter(),keyword=ref(''),topic=ref(''),loading=ref(false),error=ref(''),data=ref({content:[],page:0,totalPages:0,totalElements:0});let generation=0;
function search(){router.push({path:'/community',query:{...(keyword.value.trim()?{search:keyword.value.trim()}:{}),...(topic.value?{topic:topic.value}:{})}});}
async function load(){const ticket=++generation;keyword.value=String(route.query.search||'');topic.value=String(route.query.topic||'');loading.value=true;error.value='';try{const params=new URLSearchParams();for(const key of ['search','topic','page'])if(route.query[key])params.set(key,String(route.query[key]));const result=await request('/community/posts?'+params);if(ticket===generation)data.value=result;}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
watch(()=>route.fullPath,load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
